package retry

import "errors"

type Store interface {
	Get(key string) (string, error)
	Put(key, value string) error
}

var ErrTemporary = errors.New("temporary")
var ErrMissing = errors.New("missing")

// Ensure reads key and writes fallback only when the key is missing.
func Ensure(store Store, key, fallback string) (string, error) {
	var err error
	var value string

	for i := 0; i < 3; i++ {
		value, err = store.Get(key)
		if err == nil {
			return value, nil
		}
		if err == ErrMissing {
			break
		}
		if err == ErrTemporary {
			continue
		}
		// Permanent error
		return "", err
	}

	if err == ErrMissing {
		if putErr := store.Put(key, fallback); putErr == nil {
			return fallback, nil
		} else {
			return "", putErr
		}
	}

	return "", err
}

package cache

import (
	"container/list"
)

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get returns the value associated with the key and true if it exists.
// It also marks the key as most recently used.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache. If the key exists, it updates the value.
// If the cache is at capacity, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	if c.evictList.Len() >= c.capacity {
		// Evict the least recently used item
		last := c.evictList.Back()
		if last != nil {
			c.evictList.Remove(last)
			kv := last.Value.(*entry)
			delete(c.items, kv.key)
		}
	}

	// Add new item
	ent := &entry{key: key, value: value}
	element := c.evictList.PushFront(ent)
	c.items[key] = element
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.evictList.Len()
}

